// Update Next task in Round Robin Fashion
void update_next_task(void){
	current_task++;
	current_task %= MAX_TASK;
}

// SysTic Handler - Scheduler
__attribute__((naked)) void SysTick_Handler(void){

	/* Save the Context of Current task */

	// Stack Frame 1 - {XPSR, PC, LR, R12, R3, R2, R1, R0} automatically pushed to stack by processor

	// Get the Current Task PSP
	__asm volatile("MRS R0,PSP");

	// Using that PSP value store Stack Frame 2 - {R4 to R11}
	// Store R4 to R11 in the Memory by Decrementing the PSP with store updated PPS in RO after every STORE
	__asm volatile("STMDB R0!,{R4-R11}");

	__asm volatile("PUSH {LR}"); // preserve LR to return back to SysTic handler

	// Save Current PSP Value
	__asm volatile("BL save_current_psp_value"); // PC = save_current_psp_value with Argument as R0

	/* Retrieve the Context of Next Task*/

	// Decide next task to run
	__asm volatile("BL update_next_task"); // PC = upadte_next_task

	// Get its past PSP value
	__asm volatile("BL get_current_task_psp"); // R0 = Current Task PSP Value

	// Using that PSP value retrieve Stack Frame - 2(R4 to R11)
	// Load the Data from Memory Increment and store from R4 to R11 and store updated Address in R0 after every LOAD
	__asm volatile("LDMIA R0!,{R4-R11}");

	// Update Current task PSP
	__asm volatile("MSR PSP,R0");

	__asm volatile("POP {LR}"); // Pop LR to return back from get_current_task_psp

	__asm volatile("BX LR"); // PC = Next PSP value
}

